WITH fixes(slug,pos,q,a,why) AS (VALUES ('pcac-2026-raciocinio-logico-11-combinatoria-probabilidade',6,'Ao lançar um dado justo, a probabilidade de obter um resultado maior que 4 é 1/3.',true,'Certo. Os resultados maiores que 4 são 5 e 6: dois casos favoráveis entre seis equiprováveis. Logo, P=2/6=1/3. Conte apenas os casos que satisfazem a condição.'),
('pcac-2026-raciocinio-logico-11-combinatoria-probabilidade',7,'Ao lançar uma moeda justa e um dado justo de forma independente, a chance de obter cara e número 6 é 1/12.',true,'Certo. A chance de cara é 1/2 e a de sair 6 é 1/6. Como os experimentos são independentes, multiplique: (1/2)×(1/6)=1/12.'),
('pcac-2026-raciocinio-logico-11-combinatoria-probabilidade',9,'Em uma urna, sabendo que a bola retirada é vermelha, calcular a chance de ela ter número par é um problema de probabilidade condicional.',true,'Certo. A informação de que a bola é vermelha reduz o universo de resultados às bolas vermelhas. A chance pedida é P(par|vermelha), e não P(par) calculada sobre todas as bolas.'),
('pcac-2026-rlm-probabilidade-uniao-condicional-independencia',1,'Em um dado justo, a probabilidade de obter um número menor que 3 é 1/3.',true,'Certo. Apenas 1 e 2 são menores que 3. São dois resultados favoráveis entre seis igualmente prováveis: 2/6=1/3.'),
('pcac-2026-rlm-probabilidade-uniao-condicional-independencia',7,'Se P(A∩B)=0,12 e P(B)=0,30, então P(A|B)=0,40.',true,'Certo. Pela fórmula da probabilidade condicional, P(A|B)=P(A∩B)/P(B)=0,12/0,30=0,40. O denominador é a probabilidade do evento que já ocorreu.'),
('pcac-2026-rlm-probabilidade-uniao-condicional-independencia',8,'Se P(A)=0,4, P(B)=0,5 e A e B são independentes, então P(A∩B)=0,2.',true,'Certo. Para eventos independentes, a probabilidade da interseção é o produto: P(A∩B)=0,4×0,5=0,2. Não confunda independência com exclusão mútua.'),
('pcac-2026-raciocinio-logico-12-medias-graficos-tabelas',2,'A média ponderada das notas 5 e 9, com pesos 1 e 3 respectivamente, é 8.',true,'Certo. Média ponderada = (5×1+9×3)/(1+3)=32/4=8. O peso maior faz a nota 9 influenciar mais o resultado.'),
('pcac-2026-rlm-medias-graficos-tabelas-interpretacao',2,'Um aluno obteve notas 7 e 10, com pesos 2 e 1; sua média ponderada é 8.',true,'Certo. Some os produtos de notas e pesos: 7×2+10×1=24. Divida pela soma dos pesos, 3. A média é 24/3=8.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL THEN jsonb_set(jsonb_set(jsonb_set(e.value,'{q}',to_jsonb(f.q)),'{a}',to_jsonb(f.a)),'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;